const ESCAPES = new Map([
  ['"', '\\"'],
  ['\\', '\\\\'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

export default function jsonStringify(value) {
  return serializeProperty({ '': value }, '', []);
}

function serializeProperty(holder, key, stack) {
  let value = holder[key];
  const kind = typeof value;
  if (value !== null && (kind === 'object' || kind === 'function' || kind === 'bigint') && typeof value.toJSON === 'function') {
    value = value.toJSON(key);
  }
  if (value instanceof Number) value = Number(value);
  else if (value instanceof String) value = String(value);
  else if (value instanceof Boolean) value = value.valueOf();

  if (value === null) return 'null';
  switch (typeof value) {
    case 'boolean':
      return value ? 'true' : 'false';
    case 'number':
      return Number.isFinite(value) ? String(value) : 'null';
    case 'string':
      return quote(value);
    case 'bigint':
      throw new TypeError('Do not know how to serialize a BigInt');
    case 'object':
      return Array.isArray(value) ? serializeArray(value, stack) : serializeObject(value, stack);
    default:
      return undefined;
  }
}

function serializeArray(array, stack) {
  enter(array, stack);
  const parts = [];
  for (let index = 0; index < array.length; index += 1) {
    const item = serializeProperty(array, String(index), stack);
    parts.push(item === undefined ? 'null' : item);
  }
  stack.pop();
  return `[${parts.join(',')}]`;
}

function serializeObject(object, stack) {
  enter(object, stack);
  const parts = [];
  for (const key of Object.keys(object)) {
    const item = serializeProperty(object, key, stack);
    if (item !== undefined) parts.push(`${quote(key)}:${item}`);
  }
  stack.pop();
  return `{${parts.join(',')}}`;
}

function enter(value, stack) {
  if (stack.includes(value)) throw new TypeError('Converting circular structure to JSON');
  stack.push(value);
}

function quote(text) {
  let result = '"';
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index];
    const code = text.charCodeAt(index);
    const next = text.charCodeAt(index + 1);
    if (ESCAPES.has(char)) {
      result += ESCAPES.get(char);
    } else if (code < 0x20) {
      result += `\\u${code.toString(16).padStart(4, '0')}`;
    } else if (code >= 0xd800 && code <= 0xdbff && next >= 0xdc00 && next <= 0xdfff) {
      result += char + text[index + 1];
      index += 1;
    } else if (code >= 0xd800 && code <= 0xdfff) {
      result += `\\u${code.toString(16)}`;
    } else {
      result += char;
    }
  }
  return `${result}"`;
}

