const NEEDS_ESCAPE = /[\u0000-\u001f"\\]|[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/g;
const SHORT_ESCAPES = new Map([
  ['"', '\\"'],
  ['\\', '\\\\'],
  ['\b', '\\b'],
  ['\f', '\\f'],
  ['\n', '\\n'],
  ['\r', '\\r'],
  ['\t', '\\t'],
]);

export default function jsonStringify(value) {
  return write(value, '', new Set(), []);
}

function write(input, key, ancestors, path) {
  let value = input;
  const kind = typeof value;
  if (value !== null && (kind === 'object' || kind === 'function' || kind === 'bigint') && typeof value.toJSON === 'function') {
    value = value.toJSON(key);
  }
  if (value instanceof Number || value instanceof String || value instanceof Boolean) {
    value = value.valueOf();
  }
  if (value === null) return 'null';
  if (typeof value === 'boolean') return String(value);
  if (typeof value === 'number') return Number.isFinite(value) ? String(value) : 'null';
  if (typeof value === 'string') return quote(value);
  if (typeof value === 'bigint') throw new TypeError(`Cannot serialize a BigInt at ${formatPath(path)}`);
  if (typeof value !== 'object') return undefined;

  if (ancestors.has(value)) {
    throw new TypeError(`Converting circular structure to JSON at ${formatPath(path)}`);
  }
  ancestors.add(value);
  const container = value;
  const json = Array.isArray(container)
    ? `[${Array.from({ length: container.length }, (_, index) =>
        write(container[index], String(index), ancestors, [...path, String(index)]) ?? 'null').join(',')}]`
    : `{${Object.keys(container)
        .map((name) => [name, write(container[name], name, ancestors, [...path, name])])
        .filter(([, item]) => item !== undefined)
        .map(([name, item]) => `${quote(name)}:${item}`)
        .join(',')}}`;
  ancestors.delete(value);
  return json;
}

function quote(text) {
  const escaped = text.replace(NEEDS_ESCAPE, (char) =>
    SHORT_ESCAPES.get(char) ?? `\\u${char.charCodeAt(0).toString(16).padStart(4, '0')}`);
  return `"${escaped}"`;
}

function formatPath(path) {
  return path.length ? path.join('.') : '(root)';
}
